import{_ as a,o as e,c as r,a2 as h}from"./chunks/framework.CFuv5BrO.js";const m=JSON.parse('{"title":"文档来源与覆盖","description":"Hearth 原始路线图、十个分册、自研边界与分册 README 到本站页面的逐项映射。","frontmatter":{"title":"文档来源与覆盖","description":"Hearth 原始路线图、十个分册、自研边界与分册 README 到本站页面的逐项映射。","outline":[2,3]},"headers":[],"relativePath":"reference/source-map.md","filePath":"reference/source-map.md","lastUpdated":1793752688000}'),d={name:"reference/source-map.md"};function l(n,t,s,i,o,c){return e(),r("div",null,[...t[0]||(t[0]=[h(`<p class="eyebrow">SOURCES &amp; COVERAGE</p><h1 id="文档来源与覆盖" tabindex="-1">文档来源与覆盖 <a class="header-anchor" href="#文档来源与覆盖" aria-label="Permalink to &quot;文档来源与覆盖&quot;">​</a></h1><p class="lead">本站不是几篇独立文章，而是对原始路线图材料的主题化重组。这个页面说明每份来源文档被放到了哪里，以及哪些原始结论被完整保留。</p><h2 id="覆盖结论" tabindex="-1">覆盖结论 <a class="header-anchor" href="#覆盖结论" aria-label="Permalink to &quot;覆盖结论&quot;">​</a></h2><table tabindex="0"><thead><tr><th>审计项</th><th>结果</th></tr></thead><tbody><tr><td>原始材料</td><td>1 份完整主文档、10 个分册、1 份自研与集成边界说明、1 份分册 README</td></tr><tr><td>十个分册</td><td>全部正文块可在中文站点中逐字找到，覆盖率 100%</td></tr><tr><td>完整主文档</td><td>595/595 个正文块保留，覆盖率 100%</td></tr><tr><td>自研与集成边界</td><td>67/67 个正文块保留，覆盖率 100%</td></tr><tr><td>双语结构</td><td>每个中文页面都有路径与标题层级对应的英文页面</td></tr></tbody></table><p>审计以正文块为单位，不按字符数抽样。原始长文同时保留在<a href="/hearth-os/reference/full-roadmap.html">完整路线图归档</a>中；主题页面负责降低阅读成本，归档负责保留完整细节。</p><h2 id="原始分册-readme-结论与阅读路径" tabindex="-1">原始分册 README：结论与阅读路径 <a class="header-anchor" href="#原始分册-readme-结论与阅读路径" aria-label="Permalink to &quot;原始分册 README：结论与阅读路径&quot;">​</a></h2><p>Hearth 是一个单用户、自托管、长期驻留、低打扰、低 Token 的通用个人 Agent OS。它的核心不是“再做一个模型”，而是任务控制、持久执行、记忆、验证、审批、回执和安静的任务卡体验。</p><p>当前路线图有三条最重要的原则：</p><ol><li><strong>先做最小产品，再做完整 OS。</strong> Stage 1 内部就要出现每天可用的 MVP，不等到 Stage 6 才形成产品。</li><li><strong>前端从第一天存在。</strong> Stage 0 有可点击原型，Stage 1 有真实 Web 任务卡；每个增量都必须有用户可见路径、验证和恢复。</li><li><strong>不再按周/月排期。</strong> 第 25 章是完整的 Stage 0–6 渐进开发序列，只按能力门槛推进，不设开发时间限制。</li></ol><h3 id="产品与决策路径" tabindex="-1">产品与决策路径 <a class="header-anchor" href="#产品与决策路径" aria-label="Permalink to &quot;产品与决策路径&quot;">​</a></h3><p>适合第一次了解项目，或需要判断是否继续投入时阅读：</p><ol><li><a href="/hearth-os/product/definition.html">产品定义与设计判断</a></li><li><a href="/hearth-os/delivery/roadmap.html">分阶段产品路线图</a></li><li><a href="/hearth-os/delivery/development-plan.html">从 0 到 100 开发计划</a></li><li><a href="/hearth-os/delivery/engineering.html">工程交付、风险与决策</a></li></ol><h3 id="架构与技术路径" tabindex="-1">架构与技术路径 <a class="header-anchor" href="#架构与技术路径" aria-label="Permalink to &quot;架构与技术路径&quot;">​</a></h3><p>适合准备开始实现，或需要检查系统边界时阅读：</p><ol><li><a href="/hearth-os/architecture/overview.html">总体架构与领域协议</a></li><li><a href="/hearth-os/architecture/control-plane.html">入口、控制面与持久执行</a></li><li><a href="/hearth-os/architecture/executor-model.html">执行器体系与人工接管</a></li><li><a href="/hearth-os/architecture/execution-safety.html">执行安全、记忆与进化</a></li><li><a href="/hearth-os/architecture/token-economics.html">Token 经济与前端体验</a></li><li><a href="/hearth-os/architecture/security-privacy.html">安全隐私与评估</a></li></ol><h3 id="直接开工路径" tabindex="-1">直接开工路径 <a class="header-anchor" href="#直接开工路径" aria-label="Permalink to &quot;直接开工路径&quot;">​</a></h3><p>适合已经准备建仓库时阅读：</p><ol><li><a href="/hearth-os/delivery/development-plan.html">从 0 到 100 开发计划</a> 的 MVP 与 Stage 1 部分</li><li><a href="/hearth-os/architecture/domain-model.html">总体架构与领域协议</a></li><li><a href="/hearth-os/architecture/durable-execution.html">入口、控制面与持久执行</a></li><li><a href="/hearth-os/delivery/engineering.html">工程交付、风险与决策</a></li></ol><h2 id="原始材料到站点页面" tabindex="-1">原始材料到站点页面 <a class="header-anchor" href="#原始材料到站点页面" aria-label="Permalink to &quot;原始材料到站点页面&quot;">​</a></h2><table tabindex="0"><thead><tr><th>分册</th><th>对应主文档</th><th>读完后能回答</th></tr></thead><tbody><tr><td><a href="/hearth-os/product/definition.html">01 产品定义与设计判断</a></td><td>第 0–3 章</td><td>Hearth 为谁做、做什么、不做什么、为什么不是 Codex 套壳</td></tr><tr><td><a href="/hearth-os/architecture/overview.html">02 总体架构与领域协议</a></td><td>第 4–5 章</td><td>七个平面如何协作、核心实体和协议是什么</td></tr><tr><td><a href="/hearth-os/architecture/gateway.html">03 入口、控制面与持久执行</a></td><td>第 6–8 章</td><td>事件如何进入、如何被授权、如何可靠执行和恢复</td></tr><tr><td><a href="/hearth-os/architecture/executor-model.html">04 执行器体系与人工接管</a></td><td>第 9–16 章</td><td>Codex、Native、Connector、Browser、GUI、Document/Data、Human 如何分工</td></tr><tr><td><a href="/hearth-os/architecture/execution-safety.html">05 执行安全、记忆与进化</a></td><td>第 17–19 章</td><td>Sandbox、凭据、副作用、记忆和技能进化如何受控</td></tr><tr><td><a href="/hearth-os/architecture/token-economics.html">06 Token 经济与前端体验</a></td><td>第 20–21 章</td><td>如何控制 Token，以及用户为什么只看到任务</td></tr><tr><td><a href="/hearth-os/architecture/security-privacy.html">07 安全隐私与评估</a></td><td>第 22–23 章</td><td>信任边界、威胁模型、评测和阶段门槛是什么</td></tr><tr><td><a href="/hearth-os/delivery/roadmap.html">08 分阶段产品路线图</a></td><td>第 24 章</td><td>Stage 0–6 各自交付什么、何时算完成</td></tr><tr><td><a href="/hearth-os/delivery/development-plan.html">09 从 0 到 100 开发计划</a></td><td>第 25 章</td><td>按什么顺序开发、MVP 包含什么、每个增量如何验收</td></tr><tr><td><a href="/hearth-os/delivery/engineering.html">10 工程交付、风险与决策</a></td><td>第 26–29 章</td><td>仓库怎么建、风险如何停、ADR 和最终判断是什么</td></tr></tbody></table><h3 id="附加来源" tabindex="-1">附加来源 <a class="header-anchor" href="#附加来源" aria-label="Permalink to &quot;附加来源&quot;">​</a></h3><table tabindex="0"><thead><tr><th>来源</th><th>站点入口</th><th>处理方式</th></tr></thead><tbody><tr><td>完整主文档</td><td><a href="/hearth-os/reference/full-roadmap.html">完整路线图归档</a></td><td>逐段保留全部细节，供检索、引用和差异核对</td></tr><tr><td>自研与集成边界说明</td><td><a href="/hearth-os/reference/build-vs-integrate.html">自研与集成边界</a></td><td>保留边界结论、OpenClaw 对比和 Codex 接入规则</td></tr><tr><td>分册 README</td><td><a href="/hearth-os/guide/">开始阅读</a>、<a href="/hearth-os/guide/reading-guide.html">阅读指南</a>、本页</td><td>保留结论、三条阅读路径、十册目录与一页地图</td></tr></tbody></table><h2 id="从-0-到-100-的一页地图" tabindex="-1">从 0 到 100 的一页地图 <a class="header-anchor" href="#从-0-到-100-的一页地图" aria-label="Permalink to &quot;从 0 到 100 的一页地图&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Stage 0  产品楔子 + 可点击原型 + 协议/评测基线</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>Stage 1  走路骨架 → 第一个真实 Codex 切片 → MVP → 副作用安全 → 第二任务族</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>Stage 2  只读连接器 → 文档/数据 → 浏览器 → 草稿/审批/回执 → 日常操作员</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>Stage 3  设备 agentd → 观察/接管 → 低风险 GUI → 高风险 GUI</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>Stage 4  Trigger/主动收件箱 → 手机 PWA → 安全配对 → 注意力预算</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>Stage 5  Memory Core → 遗忘/导出 → 技能候选/评估 → 晋升/回滚</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>Stage 6  多设备同步 → 离线队列 → 撤销/密钥 → 备份迁移 → v1.0</span></span></code></pre></div><p>“100%”不是永远不再迭代，而是 Stage 6 的 v1.0 出口：完整产品、可恢复、可审批、可迁移、可撤销、可长期使用。</p><h2 id="覆盖与维护约定" tabindex="-1">覆盖与维护约定 <a class="header-anchor" href="#覆盖与维护约定" aria-label="Permalink to &quot;覆盖与维护约定&quot;">​</a></h2><ul><li><strong>主文档</strong>保留全部细节；分册用于按主题逐步阅读，不替代主文档。</li><li>每个分册开头都标明对应主文档章节和前置阅读。</li><li>文中“Stage”是能力层级，不是日期；“增量”是开发单位，不是工期承诺。</li><li>任何阶段验收都必须包含用户可见界面、持久状态、验证证据和恢复路径。</li><li>只存在于 CLI、日志或数据库中的能力，不计入阶段完成。</li></ul><p>更新来源文档时，请同步检查主题页面、完整归档和英文镜像。覆盖审计脚本位于仓库的 <code>scripts/check-coverage.py</code>，不接受用删减正文换取通过。</p>`,29)])])}const u=a(d,[["render",l]]);export{m as __pageData,u as default};
